import"./chunk-VC46IEJQ.js";var e=(i,n,a,t,h,l,r,o,s)=>({name:{en:i,zh:n},desc:{en:a[0],zh:a[1]},tour:{en:t[0],zh:t[1]},source:{confidence:h,refs:l,book:{en:r[0],zh:r[1]},unknown:{en:o[0],zh:o[1]},interpretation:{en:s[0],zh:s[1]}}}),d={id:"yin",intro:{en:"Yin is the capital of far Yi Ti, a great port on the Jade Sea reached by a river from the forests. The novels mention Yi Ti only in passing, so this scene is an openly invented impression, not a reconstruction.",zh:"\u6BB7\u57CE\u662F\u9065\u8FDC\u5937\u5730\u7684\u90FD\u57CE\uFF0C\u7389\u6D77\u4E4B\u6EE8\u7684\u5927\u6E2F\uFF0C\u4E00\u6761\u6CB3\u81EA\u68EE\u6797\u6D41\u5411\u6B64\u5730\u3002\u5C0F\u8BF4\u5BF9\u5937\u5730\u53EA\u662F\u4E00\u7B14\u5E26\u8FC7\uFF0C\u6240\u4EE5\u672C\u573A\u666F\u5B8C\u5168\u51FA\u4E8E\u60F3\u8C61\uFF0C\u5E76\u975E\u590D\u539F\u3002"},notes:{en:"From the companion book and maps only: Yin is the seat of Yi Ti's emperor, a major port on the Jade Sea, with a river running to it from the forests and a trade road north-west to Asabhad; the present emperor has little real power beyond the city. The walls, palace, pagodas and the whole look of the city - tiered roofs, vermilion, jade and gold - are invented for this atlas.",zh:"\u4EC5\u89C1\u4E8E\u8BBE\u5B9A\u96C6\u4E0E\u5730\u56FE\uFF1A\u6BB7\u57CE\u662F\u5937\u5730\u7687\u5E1D\u7684\u9A7B\u8DF8\u4E4B\u6240\uFF0C\u7389\u6D77\u4E4B\u6EE8\u7684\u91CD\u8981\u6E2F\u53E3\uFF0C\u6709\u4E00\u6761\u6CB3\u81EA\u68EE\u6797\u6D41\u6765\uFF0C\u53E6\u6709\u5546\u8DEF\u5411\u897F\u5317\u901A\u5F80\u963F\u8428\u5DF4\u5FB7\uFF1B\u5F53\u4ECA\u7687\u5E1D\u7684\u5B9E\u6743\u51E0\u4E4E\u51FA\u4E0D\u4E86\u90FD\u57CE\u3002\u57CE\u5899\u3001\u5BAB\u6BBF\u3001\u5B9D\u5854\uFF0C\u4EE5\u53CA\u6574\u5EA7\u57CE\u5E02\u7684\u6837\u8C8C\u2014\u2014\u5C42\u5C42\u98DE\u6A90\u3001\u6731\u7EA2\u3001\u78A7\u7389\u4E0E\u91D1\u8272\u2014\u2014\u5747\u4E3A\u672C\u56FE\u96C6\u81EA\u62DF\u3002"},tour:["great-port","city-walls","river-quarter","imperial-palace","tiered-pagodas","trade-road"],sources:[{ref:"twoiaf",checked:"search-snippet",note:{en:"Wiki search summaries citing the companion: Yin is the capital and court of the emperor, a great port on the Jade Sea, reached by a river from the forests, with a trade route north-west to Asabhad. The book itself was not checked.",zh:"\u636E\u5F15\u7528\u8BBE\u5B9A\u96C6\u7684\u7EF4\u57FA\u641C\u7D22\u6458\u8981\uFF1A\u6BB7\u57CE\u662F\u7687\u5E1D\u7684\u90FD\u57CE\u4E0E\u5BAB\u5EF7\u6240\u5728\uFF0C\u7389\u6D77\u4E4B\u6EE8\u7684\u5927\u6E2F\uFF0C\u6709\u6CB3\u81EA\u68EE\u6797\u6D41\u6765\uFF0C\u5E76\u6709\u5546\u8DEF\u5411\u897F\u5317\u901A\u5F80\u963F\u8428\u5DF4\u5FB7\u3002\u672A\u67E5\u9605\u539F\u4E66\u3002"}},{ref:"maps",checked:"memory",note:{en:"Yin appears on the official maps of the far east; recalled, not re-checked.",zh:"\u6BB7\u57CE\u89C1\u4E8E\u5B98\u65B9\u7684\u8FDC\u4E1C\u5730\u56FE\uFF1B\u51ED\u8BB0\u5FC6\uFF0C\u672A\u590D\u6838\u3002"}},{ref:"agot",checked:"memory",note:{en:"Yi Ti is named in passing in the novels, for example as a source of caravans at Vaes Dothrak; Yin itself is not described.",zh:"\u5C0F\u8BF4\u4E2D\u53EA\u987A\u5E26\u63D0\u53CA\u5937\u5730\uFF0C\u4F8B\u5982\u7EF4\u65AF\xB7\u591A\u65AF\u62C9\u514B\u6709\u6765\u81EA\u5937\u5730\u7684\u5546\u961F\uFF1B\u6BB7\u57CE\u672C\u8EAB\u672A\u89C1\u63CF\u5199\u3002"}}],landmarks:{"great-port":e("Great Port","\u5927\u6E2F",["A busy harbour of stone quays, junks and galleys, where the Jade Sea trade comes to the city.","\u77F3\u780C\u7801\u5934\u4E0A\u4E00\u7247\u7E41\u5FD9\uFF0C\u5927\u5E06\u8239\u4E0E\u6868\u5E06\u8239\u5F80\u6765\uFF0C\u7389\u6D77\u7684\u8D38\u6613\u5728\u6B64\u6C47\u805A\u3002"],["Yin is a port first; its wealth arrives by sea.","\u6BB7\u57CE\u9996\u5148\u662F\u4E00\u5EA7\u6E2F\u53E3\uFF0C\u8D22\u5BCC\u4ECE\u6D77\u4E0A\u6765\u3002"],"low",["twoiaf"],["Yin is a great port on the Jade Sea.","\u6BB7\u57CE\u662F\u7389\u6D77\u4E4B\u6EE8\u7684\u5927\u6E2F\u3002"],["Harbour layout and the ships that use it.","\u6E2F\u53E3\u5E03\u5C40\u4E0E\u5F80\u6765\u8239\u578B\u3002"],["A straight quay with warehouses; red-sailed junks stand in for local shipping.","\u7B14\u76F4\u7684\u7801\u5934\u914D\u4ED3\u5E93\uFF1B\u4EE5\u7EA2\u5E06\u5927\u8239\u4EE3\u8868\u672C\u5730\u8239\u53EA\u3002"]),"city-walls":e("City Walls","\u57CE\u57A3",["Rectangular walls with four gate towers under tiled roofs, drawn only as a guide to the layout.","\u65B9\u6B63\u7684\u57CE\u5899\u4E0E\u56DB\u5EA7\u8986\u74E6\u95E8\u697C\uFF0C\u4EC5\u4F5C\u5E03\u5C40\u793A\u610F\u3002"],["These walls are a guess: no source says whether Yin is walled.","\u8FD9\u4E9B\u57CE\u5899\u7EAF\u5C5E\u63A8\u6D4B\uFF1A\u6CA1\u6709\u8D44\u6599\u8BF4\u660E\u6BB7\u57CE\u662F\u5426\u7B51\u6709\u57CE\u5899\u3002"],"low",["twoiaf"],["Nothing establishes walls.","\u6CA1\u6709\u4EFB\u4F55\u8BB0\u8F7D\u63D0\u5230\u57CE\u5899\u3002"],["Whether Yin is walled at all, and how.","\u6BB7\u57CE\u662F\u5426\u6709\u57CE\u5899\uFF0C\u5F62\u5236\u5982\u4F55\u3002"],["A rectangular curtain wall with a gate on each side.","\u65B9\u5F62\u57CE\u57A3\uFF0C\u6BCF\u9762\u5F00\u4E00\u95E8\u3002"]),"river-quarter":e("River Quarter","\u6CB3\u7554\u8857\u533A",["Where the river from the forests reaches the city, crossed by a stone bridge.","\u6765\u81EA\u68EE\u6797\u7684\u6CB3\u6D41\u5728\u6B64\u5165\u57CE\uFF0C\u4E00\u5EA7\u77F3\u6865\u6A2A\u8DE8\u5176\u4E0A\u3002"],["A river from the forests brings timber and travellers to Yin.","\u68EE\u6797\u6765\u7684\u6CB3\u6D41\u4E3A\u6BB7\u57CE\u9001\u6765\u6728\u6750\u4E0E\u65C5\u4EBA\u3002"],"low",["twoiaf"],["A river runs from the forests of Yi Ti to Yin.","\u4E00\u6761\u6CB3\u4ECE\u5937\u5730\u7684\u68EE\u6797\u6D41\u5411\u6BB7\u57CE\u3002"],["The river's name, course and how it meets the city.","\u6CB3\u540D\u3001\u6CB3\u9053\uFF0C\u4EE5\u53CA\u6CB3\u4E0E\u57CE\u7684\u5173\u7CFB\u3002"],["A single stone-arched bridge on the east; invented.","\u4E1C\u4FA7\u4E00\u5EA7\u77F3\u62F1\u6865\uFF1B\u4E3A\u81EA\u62DF\u3002"]),"imperial-palace":e("Imperial Palace","\u7687\u5BAB",["A terraced palace of vermilion halls under tiered roofs, where the court sits. Entirely imagined.","\u6731\u7EA2\u6BBF\u5B87\u3001\u5C42\u5C42\u98DE\u6A90\u7684\u53F0\u5F0F\u5BAB\u6BBF\uFF0C\u5BAB\u5EF7\u6240\u5728\u3002\u5B8C\u5168\u51FA\u4E8E\u60F3\u8C61\u3002"],["The emperor holds court here, though his power barely reaches past the walls.","\u7687\u5E1D\u5728\u6B64\u4E34\u671D\uFF0C\u4F46\u4ED6\u7684\u6743\u529B\u51E0\u4E4E\u51FA\u4E0D\u4E86\u90FD\u57CE\u3002"],"low",["twoiaf"],["The emperor keeps his court at Yin and has little real power beyond the city.","\u7687\u5E1D\u7684\u5BAB\u5EF7\u8BBE\u5728\u6BB7\u57CE\uFF0C\u51FA\u4E86\u90FD\u57CE\u4FBF\u51E0\u65E0\u5B9E\u6743\u3002"],["Everything about the palace's appearance.","\u5BAB\u6BBF\u5916\u89C2\u7684\u4E00\u5207\u3002"],["Three terraces, a great hall with double eaves, and flanking pavilions.","\u4E09\u5C42\u53F0\u57FA\u3001\u91CD\u6A90\u5927\u6BBF\u4E0E\u4E24\u4FA7\u914D\u6BBF\u3002"]),"tiered-pagodas":e("Tiered Pagodas","\u591A\u5C42\u5B9D\u5854",["Slender towers of stacked roofs above the lower houses: an invented skyline.","\u5C42\u5C42\u53E0\u6A90\u7684\u7EC6\u5854\u9AD8\u51FA\u4F4E\u77EE\u6C11\u5C45\uFF0C\u662F\u865A\u6784\u7684\u5929\u9645\u7EBF\u3002"],["A skyline of stacked roofs, drawn only for mood.","\u5C42\u53E0\u5C4B\u6A90\u52FE\u52D2\u7684\u5929\u9645\u7EBF\uFF0C\u53EA\u4E3A\u8425\u9020\u6C1B\u56F4\u3002"],"low",["twoiaf"],["Nothing establishes these towers.","\u6CA1\u6709\u4EFB\u4F55\u8BB0\u8F7D\u63D0\u5230\u8FD9\u4E9B\u5854\u3002"],["Whether anything like them exists.","\u662F\u5426\u6709\u7C7B\u4F3C\u4E4B\u7269\u3002"],["Five pagodas of different heights and roof colours.","\u4E94\u5EA7\u9AD8\u4F4E\u3001\u9876\u8272\u5404\u5F02\u7684\u5B9D\u5854\u3002"]),"trade-road":e("Trade Road","\u5546\u8DEF",["The long road leaving north-west toward Asabhad.","\u5411\u897F\u5317\u51FA\u57CE\u3001\u901A\u5F80\u963F\u8428\u5DF4\u5FB7\u7684\u957F\u8DEF\u3002"],["A long road runs north-west, linking Yin with Asabhad.","\u4E00\u6761\u957F\u8DEF\u4F38\u5411\u897F\u5317\uFF0C\u8FDE\u63A5\u6BB7\u57CE\u4E0E\u963F\u8428\u5DF4\u5FB7\u3002"],"low",["twoiaf","maps"],["A trade route links Yin with Asabhad to the north-west.","\u4E00\u6761\u5546\u8DEF\u8FDE\u63A5\u6BB7\u57CE\u4E0E\u897F\u5317\u65B9\u7684\u963F\u8428\u5DF4\u5FB7\u3002"],["The road's route and length.","\u8DEF\u7EBF\u4E0E\u957F\u5EA6\u3002"],["A simple cobbled road toward the hills.","\u4E00\u6761\u901A\u5411\u5C71\u4E18\u7684\u9E45\u5375\u77F3\u8DEF\u3002"])}};export{d as default};
